fn diff_help() -> String { "usage: jet diff --structural <before.jet> <after.jet> [--json]

Compares checked Jet definitions by semantic identity.
" }

fn merge_help() -> String { "usage:
  jet merge --structural <base.jet> <ours.jet> <theirs.jet> [--out <file.jet>] [--json]
  jet merge install-driver [--repo <path>]

Performs a checked three-way structural merge or installs the opt-in Git driver.
" }
